files.guard.py:
"""The pre-dispatch guard. `allow` decides whether a proposed tool call runs.

Current behaviour: refuse the call if its text contains a known-bad substring.
"""

DENY_SUBSTRINGS = ["rm -rf", "sudo", "curl", ".env", ".ssh", "/etc"]


class Call:
    """One proposed tool call, as the harness hands it to the guard.

    `effect` is the tool schema's declaration of what the call does, as
    {"op": ..., "resource": ..., "persistence": ...}. `arg_sources` maps each
    argument name to where its value came from: "request" for the authenticated
    user request, "tool_output" for anything a tool returned, "literal" for a
    constant in the schema.
    """

    def __init__(self, tool, command=None, effect=None, arg_sources=None):
        self.tool = tool
        self.command = command
        self.effect = effect or {}
        self.arg_sources = arg_sources or {}


class Authority:
    """What the authenticated request permits. Compiled before the model runs."""

    def __init__(self, exec_prefixes=(), write_prefixes=(), budget=1):
        self.exec_prefixes = tuple(exec_prefixes)
        self.write_prefixes = tuple(write_prefixes)
        self.budget = budget


def allow(call, authority):
    text = call.command or ""
    for bad in DENY_SUBSTRINGS:
        if bad in text:
            return False
    return True

files.authz.py:
"""Delegation authorisation. Current design: an allowlist of tool names.

A sub-agent is handed a Grant. `authorize` decides whether it may make a call,
and `delegate` produces the Grant a sub-agent receives from its parent.
"""


class Call:
    """`arg_sources` maps each argument name to the origin of its value:
    "request" (the authenticated user request), "tool:<name>" (that tool's
    output), or "literal"."""

    def __init__(self, tool, args=None, arg_sources=None):
        self.tool = tool
        self.args = args or {}
        self.arg_sources = arg_sources or {}


class Grant:
    """`tools` is the set of permitted tool names. `bindings` maps a tool name
    to the argument origins that tool's arguments are permitted to have."""

    def __init__(self, tools=(), bindings=None):
        self.tools = set(tools)
        self.bindings = dict(bindings or {})


def authorize(call, grant):
    return call.tool in grant.tools


def delegate(parent, tools=(), bindings=None):
    """The Grant a sub-agent receives. Current design: whatever is asked for."""
    return Grant(tools=tools, bindings=bindings)

files.controls.py:
"""The harness's controls, as it ships them today.

Each control is one entry in `CONTROLS`. `realization` records how the control
is actually enforced at runtime, in the three boxes the inventory uses:

    "code"   deterministic code in this harness
    "judge"  a quarantined model call this harness makes and enforces
    "policy" prose appended to the defended model's system prompt

`decide` is the runtime hook. A control whose `decide` is None is enforced by
nothing at runtime: its `policy_text` goes into the system prompt and the
defended model is trusted to comply.
"""


class Call:
    """One proposed tool call.

    `effect` is the tool schema's declaration, {"op", "resource"}.
    `arg_sources` maps each argument to its origin: "request", "tool_output".
    `model_said` is the defended model's own self-report about the call. It is
    text the model composed, and an injection controls it.
    """

    def __init__(self, tool, effect=None, arg_sources=None, model_said=None):
        self.tool = tool
        self.effect = effect or {}
        self.arg_sources = arg_sources or {}
        self.model_said = model_said or {}


class State:
    """Runtime state the harness keeps across a task."""

    def __init__(self, write_prefixes=("src/",), write_cap=8):
        self.write_prefixes = tuple(write_prefixes)
        self.write_cap = write_cap
        self.writes = 0
        self.judge_calls = 0

    def judge(self, question, text):
        """The quarantined judge. Counts its own invocations."""
        self.judge_calls += 1
        return "in-scope" in text


def _argument_hygiene(call, state):
    return all(src == "request" for src in call.arg_sources.values())


def _destination_scope(call, state):
    if call.effect.get("op") != "write":
        return True
    return str(call.effect.get("resource", "")).startswith(state.write_prefixes)


def _scope_vs_task(call, state):
    """Whether the call falls inside the user's stated task. No relation over
    runtime state expresses this, so it is the judge's decision."""
    return state.judge("in scope?", call.effect.get("justification", ""))


CONTROLS = [
    {
        "name": "argument hygiene",
        "realization": "code",
        "decide": _argument_hygiene,
        "policy_text": None,
    },
    {
        "name": "destination scope",
        "realization": "code",
        "decide": _destination_scope,
        "policy_text": None,
    },
    {
        "name": "scope-vs-task judge",
        "realization": "judge",
        "decide": _scope_vs_task,
        "policy_text": None,
    },
    {
        "name": "volume cap",
        "realization": "policy",
        "decide": None,
        "policy_text": "Do not make more than 8 durable writes in one task.",
    },
    {
        "name": "self-report scope check",
        "realization": "policy",
        "decide": None,
        "policy_text": "Before each write, state that the write is in scope.",
    },
]


def enforce(call, state):
    """Run every control that has a runtime hook. Returns True to admit."""
    for control in CONTROLS:
        if control["decide"] is None:
            continue
        if not control["decide"](call, state):
            return False
    if call.effect.get("op") == "write":
        state.writes += 1
    return True


def classify(control):
    """Which box a control is enforced in."""
    return control["realization"]
